// Copy of config/feeds.md (n8n cannot read the repo). Rebuilt by n8n/build.py.
const feeds = [
  {
    "source": "MarTech",
    "url": "https://martech.org/feed/"
  },
  {
    "source": "Marketing AI Institute",
    "url": "https://www.marketingaiinstitute.com/blog/rss.xml"
  },
  {
