  },
  {
    "source": "Shopify Engineering",
    "url": "https://shopify.engineering/blog.atom"
  },
  {
    "source": "Simon Willison's Weblog",
    "url": "https://simonwillison.net/atom/everything/"
  },
  {
    "source": "Latent Space",
    "url": "https://www.latent.space/feed"
  }
];
return feeds.map(f => ({ json: f }));

// Extract From File puts the parsed JSON under .data; turn the array into items.
const d = $input.first().json;
const arr = Array.isArray(d) ? d : (Array.isArray(d.data) ? d.data : [d]);
return arr.map(j => ({ json: j }));

// One item per feed entry: title, url, source, date, excerpt. Drops stale and in-run duplicates.
const FRESH_DAYS = 7;
const cutoff = Date.now() - FRESH_DAYS * 24 * 60 * 60 * 1000;

// hostname -> source name, from the Feed list node when it ran (live path); else the hostname.
// No URL global in n8n's Code sandbox, so hostnames and query strings are handled with regex.
function hostOf(u) { const m = /^https?:\/\/([^/?#]+)/i.exec(u || ''); return m ? m[1].toLowerCase() : ''; }
const sources = {};
try { for (const f of $('Feed list').all()) sources[hostOf(f.json.url)] = f.json.source; } catch (e) {}

function cleanUrl(u) {
  const [base, q = ''] = (u || '').trim().split('#')[0].split('?');
  const kept = q.split('&').filter(p => p && !/^(utm_|mc_|ref=|source=)/i.test(p));
  return kept.length ? base + '?' + kept.join('&') : base;
}

const seen = new Set();
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const url = cleanUrl(j.link || j.guid || '');
  if (!url || seen.has(url)) continue;
  const date = j.isoDate || j.pubDate || '';
  const t = Date.parse(date);
  if (!isNaN(t) && t < cutoff) continue;
  seen.add(url);
  const host = hostOf(url);
  out.push({ json: {
    title: (j.title || '').trim(),
    url,
    source: sources[host] || host.replace(/^www\./, ''),
    date: isNaN(t) ? date : new Date(t).toISOString(),
    excerpt: (j.contentSnippet || '').replace(/\s+/g, ' ').trim().slice(0, 300),
  } });
}
return out;

// Input: every row of seen_items (one empty item if the table is empty). Output: Normalize items not in it.
const seen = new Set($input.all().map(i => i.json.url).filter(Boolean));
return $('Normalize').all().filter(i => !seen.has(i.json.url));

// All unseen items -> one request to the Researcher. No items -> stop quietly (nothing to digest).
const items = $input.all().map(i => i.json);
if (!items.length) return [];
const user = 'Week items as JSON:
' + JSON.stringify(items);
return [{ json: { count: items.length, body: { model: "claude-haiku-5-5", max_tokens: 8000, system: "You are the Researcher in a weekly three-agent signal scout. You receive the new feed items of the week (title, url, source, date, excerpt) that have not been seen before. Your only job is a relevance screen: mark each item keep=true if it plausibly belongs to the topic brief, keep=false otherwise, with a reason of at most 12 words. Keep borderline items; the Editor cuts later. Return every input url exactly once.

TOPIC BRIEF. This scout watches two things only: (1) AI adoption in marketing operations: how marketing and ops teams actually put AI to work in planning, intake, content production, campaign execution, martech stacks, reporting, and the operating model around them; (2) agent readiness: what it takes for a company, its data, its systems, its content and its commerce surfaces to be used by AI agents (protocols like MCP, agentic commerce and payments, agent-accessible catalogs and APIs, governance of agents at work). Pure model research, consumer gadgets, funding news, and generic productivity tips are off-topic unless an item ties them to one of the two.

CLAIM RULE. Never state a fact that is not in the item you were given. Never invent a number, a quote, a company action or a date. Never alter a URL: return URLs exactly as received, and only URLs that were in your input. If an item's excerpt is too thin to support a statement, say less, not more.

RUN LOGGING. Every call you make is logged with model, input tokens, output tokens and cost, and the run is capped. Return only the JSON asked for: no preamble, no commentary, no markdown fences, nothing padded.", output_config: { effort: "low", format: { type: 'json_schema', schema: {"type": "object", "properties": {"items": {"type": "array", "items": {"type": "object", "properties": {"url": {"type": "string"}, "keep": {"type": "boolean"}, "reason": {"type": "string"}}, "required": ["url", "keep", "reason"], "additionalProperties": false}}}, "required": ["items"], "additionalProperties": false} } }, messages: [{ role: 'user', content: user }] } } }];

// Structured outputs: first content block is text holding valid JSON.
function parsed(resp) {
  const block = (resp.content || []).find(b => b.type === 'text');
  if (!block) throw new Error('No text block in model response: stop_reason=' + resp.stop_reason);
  return JSON.parse(block.text);
}
function byUrl(items) { const m = new Map(); for (const i of items) m.set(i.url, i); return m; }

// Join the Researcher's verdicts back onto the original records: the model never rewrites an item.
const input = byUrl(JSON.parse($('Pack items').first().json.body.messages[0].content.replace(/^[^\n]*\n/, '')));
const out = parsed($input.first().json);
const kept = [];
for (const v of out.items || []) if (v.keep && input.has(v.url)) kept.push(input.get(v.url));
if (!kept.length) throw new Error('Researcher kept 0 of ' + input.size + ' items');
const user = 'Items as JSON:\n' + JSON.stringify(kept);
return [{ json: { kept: kept.length, body: { model: "claude-haiku-5-5", max_tokens: 8000, system: "You are the Summarizer in a weekly three-agent signal scout. For each item (title, url, source, date, excerpt) write a two-sentence summary of what the item says, using only what the item contains, and give it exactly one tag: 'marketing-ops-ai' (AI adoption in marketing operations), 'agent-readiness' (what it takes to be used by agents: protocols, agentic commerce, agent governance), or 'other'. Return every input url exactly once.\n\nTOPIC BRIEF. This scout watches two things only: (1) AI adoption in marketing operations: how marketing and ops teams actually put AI to work in planning, intake, content production, campaign execution, martech stacks, reporting, and the operating model around them; (2) agent readiness: what it takes for a company, its data, its systems, its content and its commerce surfaces to be used by AI agents (protocols like MCP, agentic commerce and payments, agent-accessible catalogs and APIs, governance of agents at work). Pure model research, consumer gadgets, funding news, and generic productivity tips are off-topic unless an item ties them to one of the two.\n\nCLAIM RULE. Never state a fact that is not in the item you were given. Never invent a number, a quote, a company action or a date. Never alter a URL: return URLs exactly as received, and only URLs that were in your input. If an item's excerpt is too thin to support a statement, say less, not more.\n\nRUN LOGGING. Every call you make is logged with model, input tokens, output tokens and cost, and the run is capped. Return only the JSON asked for: no preamble, no commentary, no markdown fences, nothing padded.", output_config: { effort: "low", format: { type: 'json_schema', schema: {"type": "object", "properties": {"items": {"type": "array", "items": {"type": "object", "properties": {"url": {"type": "string"}, "summary": {"type": "string"}, "tag": {"type": "string", "enum": ["marketing-ops-ai", "agent-readiness", "other"]}}, "required": ["url", "summary", "tag"], "additionalProperties": false}}}, "required": ["items"], "additionalProperties": false} } }, messages: [{ role: 'user', content: user }] } } }];

// Structured outputs: first content block is text holding valid JSON.
function parsed(resp) {
  const block = (resp.content || []).find(b => b.type === 'text');
  if (!block) throw new Error('No text block in model response: stop_reason=' + resp.stop_reason);
  return JSON.parse(block.text);
}
function byUrl(items) { const m = new Map(); for (const i of items) m.set(i.url, i); return m; }

const kept = byUrl(JSON.parse($('After Researcher').first().json.body.messages[0].content.replace(/^[^\n]*\n/, '')));
const out = parsed($input.first().json);
const summarized = [];
for (const s of out.items || []) {
  const rec = kept.get(s.url);
  if (!rec) continue;  // claim rule: unknown url, dropped
  summarized.push({ ...rec, summary: s.summary, tag: s.tag });
}
if (!summarized.length) throw new Error('Summarizer returned 0 known items');
const user = 'Summarized items as JSON:\n' + JSON.stringify(summarized);
return [{ json: { summarized: summarized.length, body: { model: "claude-sonnet-5-5", max_tokens: 4000, system: "You are the Editor in a weekly three-agent signal scout. You receive summarized, tagged items. Keep the 5 to 8 best for a weekly digest that feeds LinkedIn posts: cut everything tagged 'other', cut duplicates of the same story (keep the primary source), and prefer items with a concrete number, decision or thing that broke over announcements. For each pick write a one-line post angle in the brand voice and a why of at most 15 words. Write a two-sentence intro for the digest that names the week's main thread. If fewer than 5 items are on topic, pick fewer and say so in the intro; never pad with off-topic items.\n\nTOPIC BRIEF. This scout watches two things only: (1) AI adoption in marketing operations: how marketing and ops teams actually put AI to work in planning, intake, content production, campaign execution, martech stacks, reporting, and the operating model around them; (2) agent readiness: what it takes for a company, its data, its systems, its content and its commerce surfaces to be used by AI agents (protocols like MCP, agentic commerce and payments, agent-accessible catalogs and APIs, governance of agents at work). Pure model research, consumer gadgets, funding news, and generic productivity tips are off-topic unless an item ties them to one of the two.\n\nCLAIM RULE. Never state a fact that is not in the item you were given. Never invent a number, a quote, a company action or a date. Never alter a URL: return URLs exactly as received, and only URLs that were in your input. If an item's excerpt is too thin to support a statement, say less, not more.\n\nBRAND VOICE (for post angles). The reader is Shane LaBounty: a senior marketing-operations leader who ran $100M+ marketing budgets, 1,000+ projects a year and a 150-marketer martech stack, and now tests AI against that world and reports what held and what broke. Experience first, experiment second. Specific over general: one real number or moment beats polished generalities. Warm, direct, first person, contractions fine. Never hype, never beginner voice ('I'm learning AI'), never a pitch. Never use: 'excited to share', 'humbled', 'game-changer', 'hope this finds you well', 'pick your brain', 'synergy', 'circle back', emoji. A post angle is one sentence, at most 25 words, that a CMO who has never met Shane would read and think 'that person has done the work'. It must be defensible from the item alone.\n\nRUN LOGGING. Every call you make is logged with model, input tokens, output tokens and cost, and the run is capped. Return only the JSON asked for: no preamble, no commentary, no markdown fences, nothing padded.", output_config: { effort: "medium", format: { type: 'json_schema', schema: {"type": "object", "properties": {"intro": {"type": "string"}, "picks": {"type": "array", "items": {"type": "object", "properties": {"url": {"type": "string"}, "post_angle": {"type": "string"}, "why": {"type": "string"}}, "required": ["url", "post_angle", "why"], "additionalProperties": false}}}, "required": ["intro", "picks"], "additionalProperties": false} } }, messages: [{ role: 'user', content: user }] } } }];

// Structured outputs: first content block is text holding valid JSON.
function parsed(resp) {
  const block = (resp.content || []).find(b => b.type === 'text');
  if (!block) throw new Error('No text block in model response: stop_reason=' + resp.stop_reason);
  return JSON.parse(block.text);
}
function byUrl(items) { const m = new Map(); for (const i of items) m.set(i.url, i); return m; }

// Deterministic digest: every link and fact comes from the item record, the model only adds angle, why, intro.
const PRICES = {"claude-haiku-5-5": [0.1, 0.5], "claude-sonnet-5-5": [2.0, 10.0]};
const summarized = byUrl(JSON.parse($('After Summarizer').first().json.body.messages[0].content.replace(/^[^\n]*\n/, '')));
const out = parsed($input.first().json);
const picks = [];
for (const p of out.picks || []) { const rec = summarized.get(p.url); if (rec) picks.push({ ...rec, post_angle: p.post_angle, why: p.why }); }
if (!picks.length) throw new Error('Editor picked 0 known items');

const now = new Date();
const monday = new Date(now); monday.setUTCDate(now.getUTCDate() - ((now.getUTCDay() + 6) % 7));
const week = monday.toISOString().slice(0, 10);
const runAt = now.toISOString();

const usages = [
  ['Researcher', $('Researcher').first().json],
  ['Summarizer', $('Summarizer').first().json],
  ['Editor', $input.first().json],
].map(([agent, r]) => {
  const u = r.usage || {}; const [pin, pout] = PRICES[r.model] || [0, 0];
  const cost = (u.input_tokens || 0) * pin / 1e6 + (u.output_tokens || 0) * pout / 1e6;
  return { run_at: runAt, agent, model: r.model, input_tokens: u.input_tokens || 0, output_tokens: u.output_tokens || 0, cost_usd: Math.round(cost * 1e6) / 1e6, status: 'ok', note: 'stop=' + r.stop_reason };
});
const total = usages.reduce((a, u) => a + u.cost_usd, 0);
const counts = { fresh: $('Pack items').first().json.count, kept: $('After Researcher').first().json.kept, summarized: $('After Summarizer').first().json.summarized, picked: picks.length };

const lines = [`# Signal Scout — week of ${week}`, '',
  `_Run ${runAt} · ${counts.fresh} new items from ${$('Feed list').all().length || 'the'} feeds · ${counts.kept} passed the Researcher · ${counts.picked} picked._`, '',
  out.intro || '', ''];
picks.forEach((p, i) => {
  lines.push(`## ${i + 1}. ${p.title}`, `**${p.source}** · ${(p.date || '').slice(0, 10)} · ${p.url}`, '', p.summary, '',
    `Tag: ${p.tag}`, '', `**Post angle:** ${p.post_angle}`, '', `_Why: ${p.why}_`, '');
});
lines.push('---', `Cost this run: ${usages.map(u => `${u.agent} ${u.model} ${u.input_tokens}→${u.output_tokens} tok $${u.cost_usd.toFixed(4)}`).join(' · ')} · total $${total.toFixed(4)}`, '');

return [{ json: { week, run_at: runAt, file_name: `Signal Scout — week of ${week}.md`, digest_md: lines.join('\n'), picks: picks.map(p => ({ url: p.url, title: p.title, source: p.source })), usages, counts, total_cost_usd: total } }];

// Error Trigger payload -> one run_log row. Nothing is marked seen on this path (AC 3).
const e = $input.first().json;
const err = (e.execution && e.execution.error) || {};
return [{ json: { run_at: new Date().toISOString(), agent: 'workflow', model: '', input_tokens: 0, output_tokens: 0, cost_usd: 0,
  status: 'error', note: ((e.execution && e.execution.lastNodeExecuted) || '?') + ': ' + String(err.message || err).slice(0, 400) } }];
